int main(int argc,char**argv){assert(argc==2);std::vector<uint8_t> bytes;std::ifstream file(argv[1],std::ios::binary);bytes.resize(32);assert(file.read(reinterpret_cast<char*>(bytes.data()),32));bytes.resize(size_t(groove::SoundBank::u32(bytes,24))+groove::SoundBank::u32(bytes,28));assert(file.read(reinterpret_cast<char*>(bytes.data()+32),bytes.size()-32));auto bank=std::make_unique<groove::SoundBank>();assert(bank->parse(bytes));assert(bank->loaded&&bank->patternCount>0&&bank->patternLength==15360);for(int i=0;i<64;++i){assert(bank->sounds[i].numFrames()>1);assert(std::strlen(bank->ids[i].data())==64);}std::cout<<"PASS64WAV records, sample IDs, source rate/channels/frames and108MIDI note-ons\n";auto bad=bytes;bad.back()=0xff;assert(!bank->parse(bad));bad=bytes;bad[32+80]=0xff;bad[32+81]=0xff;bad[32+82]=0xff;bad[32+83]=0xff;assert(!bank->parse(bad));bad=bytes;bad[0]='X';assert(!bank->parse(bad));bad=bytes;bad.resize(50);assert(!bank->parse(bad));bad=bytes;bad[7000]^=0xff;assert(!bank->parse(bad));assert(bank->parse(bytes));std::cout<<"PASS malformed/truncated/offset-corrupt/checksum-corrupt bank rejected\n";}
